cards=""
for gid,t,p,ev,fix,imp in G:
  evh="".join(f'<li><span class="d">{D.get(i,"date unknown")}</span> <a href="{R}{i}" target="_blank" rel="noopener">{i}</a> {html.escape(d)}</li>' for i,d in ev)
  ds=[D[i] for i,_ in ev if i in D]; first=min(ds); days=(CHK-datetime.date.fromisoformat(first)).days
  dur=f'<div class="dur"><div><span class="big">{days}</span> days open</div><div>First reported <b>{first}</b></div><div>Last checked <b>{CHK}</b>: no resolution recorded in CleanApp*</div><div>{len(ev)} report(s)</div></div>' 
  cards+=f'''<article class="gip" id="{gid.lower()}" data-days="{days}" data-rank="{gid[4:]}"><header><span class="id">{gid}</span><h3>{html.escape(t)}</h3></header>{dur}
<dl><dt>Problem</dt><dd>{html.escape(p)}</dd><dt>Evidence</dt><dd><ul>{evh}</ul></dd><dt>Proposed fix</dt><dd>{html.escape(fix)}</dd><dt>Impact <em>(estimate)</em></dt><dd>{html.escape(imp)}</dd></dl></article>'''
toc="".join(f'<li><a href="#{g[0].lower()}"><b>{g[0]}</b> {html.escape(g[1])}</a></li>' for g in G)
page=open('template.html').read().replace('{{CARDS}}',cards).replace('{{TOC}}',toc)
open('index.html','w').write(page)
json.dump([dict(id=g[0],title=g[1],evidence=[e[0] for e in g[3]]) for g in G],open('gips.json','w'),indent=1)
